import { tool } from "../../tool/index.js";
import { buildInvokeAgentFollowupInstruction, FIRST_TURN_STARTER_INTENT_ROOT_OWNERSHIP_BLOCK_MESSAGE, FIRST_TURN_STARTER_INTENT_ROOT_OWNERSHIP_CONTEXT_KEY, isStarterIntentRootOwnershipRequired, } from "../conversation/delegation-policy.js";
import { buildHostedChildToolDescription } from "./child-requested-tools.js";
import { shouldBlockHostedChildSameTurnRetry } from "./child-status.js";
